"""Build the Russian #249 report draft (bare semantic HTML with render-kit markers) from metrics.json. Prose follows ASD-STE100 rules in Russian."""
import json, sys, html
R = sys.argv[1]; m = json.load(open(f"{R}/metrics.json")); E = html.escape
def row(cells, th=False):
    t = "th" if th else "td"; return "<tr>" + "".join(f"<{t}>{c}</{t}>" for c in cells) + "</tr>"
arms = ["baseline", "candidate"]; AR = {"baseline": "базовое", "candidate": "кандидат"}
CAT = {"regression-insensitive": "тест не чувствует регрессию", "implementation-coupling": "тест привязан к реализации", "reimplemented-production-logic": "стаб переписывает правило production"}
PAIR = {"pair-2": "пара 2", "pair-3": "пара 3", "pair-4": "пара 4"}
hits = [row(["Пара", "Категория", "Плечо", "плохих раундов", "поисковик назвал", "в финале", "потеряно в конвейере", "починенных раундов", "ложных"], True)]
for pair, v in m["pairs"].items():
    for a in arms:
        s = v[a]; hits.append(row([PAIR[pair] if a == "baseline" else "", CAT[v["category"]] if a == "baseline" else "", AR[a], s["bad_rounds"], s["found_hits"], s["final_hits"], s["lost_in_pipeline"], s["repaired_rounds"], s["false_positives"]]))
tot = {a: {k: sum(v[a][k] for v in m["pairs"].values()) for k in ("bad_rounds", "found_hits", "final_hits", "repaired_rounds", "false_positives")} for a in arms}
for a in arms:
    t = tot[a]; hits.append(row(["<strong>все пары</strong>" if a == "baseline" else "", "", f"<strong>{AR[a]}</strong>", t["bad_rounds"], f"<strong>{t['found_hits']}</strong>", f"<strong>{t['final_hits']}</strong>", "", t["repaired_rounds"], f"<strong>{t['false_positives']}</strong>"]))
cost = [row(["Плечо", "Раундов", "Деградировало", "Токенов на раунд", "Claude на раунд", "Codex на раунд", "агент docs+tests на раунд", "Минут на раунд", "Находок в финале на раунд"], True)]
for a in arms:
    c = m["cost"][a]["total"]; n = c["rounds"]
    cost.append(row([AR[a], n, c["degraded"], f"{c['tokens']/n/1e6:.1f}M", f"{c['claude']/n/1e6:.1f}M", f"{c['codex']/n/1e6:.2f}M", f"{c['docs_tests']/n/1e6:.2f}M", f"{c['ms']/n/60000:.1f}", f"{c['final_findings']/n:.1f}"]))
LAB = {
 "pair-2": ("Тесты расширения Pi для brew требовали пустой список уведомлений после таймаута и после ненулевого кода команды. Тесты защищали молчание при сбое.", "Основание: PR #135 и его прогон, где 6 тестов упали на старом коде."),
 "pair-3": ("Тесты жизненного цикла herdr-child ждали исторический alias <code>orange-panda</code>. Ожидание шло из того же аллокатора, что и проверяемое значение.", "Основание: PR #167 и аудит в старом документе #249."),
 "pair-4": ("Стаб Herdr в <code>tests/helpers/herdr_task_sync.bash</code> принимал равный номер последовательности. Production его отвергает. Тесты принимали записи, которые production игнорирует.", "Основание: PR #115 и аудит в старом документе #249."),
}
labels = "".join(f"<dt>{PAIR[p]} · {CAT[m['pairs'][p]['category']]}</dt><dd>{LAB[p][0]} <small>{LAB[p][1]}</small></dd>" for p in m["pairs"])
notes = []
ST = {"bad": "плохой", "repaired": "починенный"}
for a in arms:
    for r in m["rows"][a]:
        tag = "<ins>попадание</ins>" if r.get("final_hit") else ("<mark>только поисковик</mark>" if r.get("found_hit") else ("<del>ложное</del>" if r.get("false_positive") else "<small>нет</small>"))
        notes.append(row([AR[a], PAIR[r["pair"]], ST[r["stage"]], r["task"].split("#")[1].replace("rep", ""), tag, E(r.get("note", ""))]))
block = E(open(f"{R}/candidate-block.md").read().strip())
page = f"""<!doctype html><html lang="ru"><head><title>Линза tests в revmux: измерение #249</title>
<!-- kit: head -->
<!-- kit: components -->
</head><body><main lang="ru">
<hgroup><h1>Помогает ли один блок в линзе <code>tests</code> видеть слабые тесты?</h1>
<p>Issue #249 · базовое плечо: профиль <code>lean</code> без изменений · 28 октября 2026 · 36 раундов, слепая разметка</p></hgroup>
<nav aria-label="Содержание"><ul><li><a href="#q">Ответ</a></li><li><a href="#terms">Термины</a></li><li><a href="#setup">Условия</a></li><li><a href="#hits">Попадания и ложные</a></li><li><a href="#cost">Цена</a></li><li><a href="#notes">Вердикты по раундам</a></li><li><a href="#limits">Ограничения</a></li><li><a href="#next">Дальше</a></li></ul></nav>
<h2 id="q">Ответ</h2>
<p><del>Нет. Линза <code>tests</code> остаётся без изменений.</del> Кандидат улучшил один вердикт из девяти и ухудшил три. Один слепой разметчик на пару судил оба плеча вместе.</p>
<ul>
<li>Пара 2, тесты защищали молчание при сбое. Базовое плечо назвало дефект в 3 из 3 проходов поисковиков и в 2 из 3 финальных списков. Кандидат назвал его в 3 из 3 финальных списков. Разница в один раунд. Пилот #408 показал шум повторов такого же размера.</li>
<li>Пара 3, тесты ждали исторический alias. Ни одно плечо не назвало размеченный дефект ни в одном раунде. Агент <code>docs+tests</code> кандидата дал новую находку во всех трёх починенных раундах. Находка повторяет слова блока: починенные тесты берут ожидаемый alias «из того, что выбрал сам аллокатор». Разметчик считает её ложной относительно разметки. Последняя фраза находки звучит как замечание о покрытии: «Дрейф распространения ловится. Аллокация нет». В любом случае это новый вывод о правильном фиксе. Он дошёл до финального списка каждый раз. Базовое плечо его не дало.</li>
<li>Пара 4, стаб принимал то, что production отвергает. Ни один поисковик ни в одном плече не назвал дефект за шесть плохих раундов. Первый пункт блока описывает именно этот дефект.</li>
</ul>
<p>Issue допускает результат без изменений. Это такой результат. Измерение дало два вывода о методе. Раздельные разметчики по плечам разошлись на одинаковой находке, см. ниже. Базовый <code>lean</code> уже ловит категорию «тест не чувствует регрессию» в 2 из 3.</p>
<h2 id="terms">Термины</h2>
<dl>
<dt>Плечо</dt><dd>Один вариант промпта. Базовое плечо равно профилю <code>lean</code> без изменений. Кандидат равен тому же профилю с одним блоком в линзе <code>tests</code>.</dd>
<dt>Пара</dt><dd>Два коммита одного дефекта. Плохой коммит внёс слабый тест. Починенный коммит исправил его.</dd>
<dt>Раунд</dt><dd>Один прогон revmux: одно плечо, один коммит, один повтор.</dd>
<dt>Попадание</dt><dd>Находка, которая называет тот же тест и ту же причину слабости, что и разметка. Попадание на уровне поисковика: любой кандидат от агентов. Попадание в финале: находка финального списка.</dd>
<dt>Ложное</dt><dd>Находка финального списка на починенном коммите, которая утверждает дефект, которого в коде нет.</dd>
</dl>
<h2 id="setup">Условия</h2>
<dl>
<dt>Базовое плечо</dt><dd>Профиль <code>lean</code>: пять поисковиков, три группы Claude opus 5.5 и две группы Codex gpt-6.1-sol. Синтез и проверка на opus:high. Линза <code>tests</code> равна встроенному тексту revmux.</dd>
<dt>Кандидат</dt><dd>Тот же профиль плюс один блок в линзе <code>tests</code>, двенадцать строк. Блок просит спросить, откуда тест берёт ожидаемое значение. Блок называет два источника, которые делают тест зелёным по построению: фейк, который переписывает правило production, и ожидаемое значение из того же хелпера, аллокатора, таблицы или пути, что и проверяемое. Больше ничего в промпте не менялось. Diff собранного промпта поисковика равен этому блоку.</dd>
<dt>Кейсы</dt><dd>Три размеченные пары из диапазонов #249. Пара 1 корпуса, миграция с Bats на bashunit на 21 тысячу строк, исключена из-за размера. Каждый из шести коммитов прошёл три раза в каждом плече. Итого 18 раундов на плечо, 36 всего. Ни один раунд не деградировал.</dd>
<dt>Разметка</dt><dd><dl>{labels}</dl></dd>
<dt>Разметчик</dt><dd>Один агент OpenCode gpt-5.6-terra на пару. Агент читал все двенадцать раундов пары под непрозрачными id раундов. Агент видел размеченный дефект и замороженный код. Для каждого раунда агент записал попадание на уровне поисковика, попадание в финале и ложные находки на починенных раундах. Агент не видел имена плеч.</dd>
</dl>
<h2 id="hits">Попадания и ложные</h2>
<table>{''.join(hits)}</table>
<p>Таблица показывает перекрёстную разметку: один судья на пару для обоих плеч. Первый проход был другим: один разметчик на плечо. Этот проход отдал пару 3 кандидату со счётом 3:0 по финальным попаданиям. Разметчик кандидата принял находку «callback-тесты не отличают живой alias от alias запуска» за размеченный дефект. Разметчик базового плеча отверг ту же находку в раундах базового плеча. Находка есть во всех трёх плохих раундах базового плеча: <code>docs+tests-4</code>, <code>arch+quality-4</code>, <code>lean-4</code>. Перекрёстный судья отверг её в обоих плечах. Это совпадает с разметкой: фикс в PR #167 переписал тесты жизненного цикла, не callback-тесты. Первый проход сохранён в <code>metrics.json</code> под ключом <code>separate</code>. Он также записал базовому плечу одно ложное на паре 4, которое перекрёстный судья не подтвердил.</p>
<h2 id="cost">Цена</h2>
<table>{''.join(cost)}</table>
<h2 id="notes">Вердикты по раундам</h2>
<details><summary>36 строк, одна на раунд, с фразой разметчика на английском</summary><table>{row(["Плечо","Пара","Коммит","Повтор","Итог","Заметка разметчика"], True)}{''.join(notes)}</table></details>
<h2 id="limits">Ограничения</h2>
<ul>
<li>Три пары, девять плохих раундов на плечо. Изменение линзы, которое помогает одной категории из десяти, здесь не видно. Пара 1 корпуса исключена из-за размера.</li>
<li>Разметчик равен модели gpt-5.6-terra, effort high, один на пару. Он не видел плечо. Он видел стадию коммита, плохой или починенный. Это нужно для вопроса о ложных находках.</li>
<li>Каждый плохой коммит также содержит большое изменение production. Пара 3 трогает 37 файлов. Пара 4 переносит harness на 1100 строк. Поисковики делят внимание между кодом и тестами. Дефекты пар 3 и 4 лежат в хелперах и стабах тестов. Scope просил агентов прочитать эти файлы целиком.</li>
<li>Кандидат равен одному блоку из двенадцати строк в одной линзе одного из пяти поисковиков. Результат ничего не говорит про изменение промпта стадии и про отдельного агента для доказательств тестов. Это два других варианта из #249.</li>
<li>Блок линзы, который прошёл измерение, на английском:<pre><code class="language-md">{block}</code></pre></li>
</ul>
<h2 id="next">Дальше</h2>
<ul>
<li>Записать результат без изменений на #249. Базовый <code>lean</code> сохраняет встроенную линзу <code>tests</code>.</li>
<li>Если работа по #249 продолжится, следующий кандидат не равен новому тексту линзы. Обе пропущенные категории требуют, чтобы ревьюер открыл стаб и сравнил его с production. Это инструкция чтения в scope или отдельный агент с двумя названными файлами. Это не пункт в списке из восьми.</li>
<li>Использовать перекрёстную разметку для решающего прогона #408: один судья на кейс для всех плеч под непрозрачными id. Разметчики по плечам здесь разошлись на одинаковой находке.</li>
</ul>
</main>
<!-- kit: scripts -->
</body></html>"""
open(f"{R}/draft-ru.html", "w").write(page); print("draft written", len(page))
